def countCycleComponents(n, edges):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    seen = [False] * n
    rings = 0
    for s in range(n):
        if seen[s]:
            continue
        seen[s] = True
        stack = [s]
        ok = True
        while stack:
            u = stack.pop()
            if len(adj[u]) != 2:
                ok = False
            for v in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
        if ok:
            rings += 1
    return rings
